const formData = JSON.parse($input.first().json.body);

// Sanitize strings
for (const key in formData) {
  if (typeof formData[key] === 'string') {
    formData[key] = formData[key]
      .replace(/\\/g, '\\\\')
      .replace(/"/g, '\\"')
      .replace(/\n/g, ' ')
      .replace(/\r/g, '')
      .replace(/\t/g, ' ');
  }
}

// Ensure _kylas IDs are never null — use 0 as safe fallback
if (formData._kylas) {
  if (!formData._kylas.time_slot_id) formData._kylas.time_slot_id = 0;
  if (!formData._kylas.source_id) formData._kylas.source_id = 0;
  if (!formData._kylas.sub_source_id) formData._kylas.sub_source_id = 0;
  if (!formData._kylas.lead_type_id) formData._kylas.lead_type_id = 0;
}

return { json: formData };

const d = $input.first().json;

const payload = {
  firstName: d.full_name || '',
  lastName: 'Custom Form',
  phoneNumbers: [{
    type: 'MOBILE',
    code: 'IN',
    value: d.whatsapp ? d.whatsapp.replace((d.dial_code || '+91') + ' ', '') : '',
    dialCode: d.dial_code || '+91',
    primary: true
  }],
  emails: [{
    type: 'OFFICE',
    value: d.email || '',
    primary: true
  }],
  source: d._kylas && d._kylas.source_id ? d._kylas.source_id : null,
  utmSource: d.utm_source || '',
  utmMedium: d.utm_medium || '',
  utmCampaign: d.utm_campaign || '',
  utmContent: d.utm_content || '',
  utmTerm: d.utm_term || '',
  customFieldValues: {
    cfCity: d.city || '',
    cfWhatIsYourCurrentProfessionBusiness: d.profession || '',
    cfEnquiryFor: d.enquiry_for || '',
    cfTellUsTheMainReasonWhyYouWantToLearn: d.reason || '',
    cfLeadType: d._kylas && d._kylas.lead_type_id ? [d._kylas.lead_type_id] : [],
    cfSubSourceMultiPicklist: d._kylas && d._kylas.sub_source_id ? [d._kylas.sub_source_id] : []
  }
};

if (d._kylas && d._kylas.time_slot_id) {
  payload.customFieldValues.cfWhatIsTheBestTimeToCallYou = d._kylas.time_slot_id;
}

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.kylas.io/v1/leads/',
  headers: {
    'Content-Type': 'application/json',
    'api-key': 'YOUR_SECRET'
  },
  body: payload,
  json: true,
  returnFullResponse: true
});

return { json: { status: response.statusCode, lead: response.body, payload_sent: payload } };

const d = $input.first().json;

const LEAD_TYPE_MAP = {
  'DM': 2794436,
  'AI': 2794437,
  'SOS': 2794438,
  'AI for Kids': 2867807,
  'EOS': 2898462,
  'FFL': 2867808,
  'ABR': 2898507,
  '21DC': 2898483
};

function detectLeadType(enquiry, sheetLeadType) {
  // If user selected an enquiry option, detect from that
  if (enquiry && enquiry.trim()) {
    var q = enquiry.toLowerCase();

    if (q.indexOf('ai') !== -1 && q.indexOf('kids') !== -1) return 'AI for Kids';
    if (q.indexOf('entrepreneurship') !== -1 && q.indexOf('kids') !== -1) return 'FFL';
    if (q.indexOf('business') !== -1 && q.indexOf('kids') !== -1) return 'FFL';
    if (q.indexOf('founders') !== -1 || q.indexOf('ffl') !== -1) return 'FFL';
    if (q.indexOf('digital') !== -1) return 'DM';
    if (q.indexOf('ai') !== -1 || q.indexOf('genai') !== -1) return 'AI';
    if (q.indexOf('sales') !== -1 || q.indexOf('selling') !== -1) return 'SOS';
    if (q.indexOf('21dc') !== -1) return '21DC';
    if (q.indexOf('entrepreneurship') !== -1) return 'EOS';
  }

  // No enquiry data — fall back to sheet's lead_type
  if (sheetLeadType && sheetLeadType.trim()) return sheetLeadType.trim();

  // Nothing at all — empty
  return '';
}

const leadTypeLabel = detectLeadType(d.enquiry_for || '', d.lead_type || '');
const leadTypeId = LEAD_TYPE_MAP[leadTypeLabel] || null;

d.lead_type = leadTypeLabel;
if (!d._kylas) d._kylas = {};
d._kylas.lead_type_id = leadTypeId;

return { json: d };
